import math


def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()


def build_agent(sandbox):
    return sandbox.get_seeker_body()


def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0, 'last_ty': 0.0,
            'tvx': 0.0, 'tvy': 0.0,
            'cooldown_remaining': 0,
            'last_step': 0,
        }
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Update target velocity estimate
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Activation check
    activation_streak = 0
    if 13.0 <= sx <= 17.0:
        activation_streak += 1
    else:
        activation_streak = 0

    if activation_streak < 80:
        # Move towards activation zone
        gx = 13.0 if (step_count // 120) % 2 == 0 else 17.0
        gy = 1.35
        desired_dir = math.atan2(gy - sy, gx - sx)
        max_force = 80.0  # Reduced to avoid cooldown
        fx = max_force * math.cos(desired_dir)
        fy = max_force * math.sin(desired_dir)
        sandbox.apply_seeker_force(fx, fy)
    else:
        # Activated, handle rendezvous
        if in_slot:
            # Determine reference direction
            target_speed = math.hypot(state['tvx'], state['tvy'])
            if target_speed >= 0.15:
                desired_dir = math.atan2(state['tvy'], state['tvx'])
            else:
                desired_dir = math.atan2(ty - sy, tx - sx)

            # Calculate relative speed
            relative_speed = math.hypot(state['tvx'] - svx, state['tvy'] - svy)
            if relative_speed > 1.5:
                max_force = 80.0 * (1.5 / relative_speed)
            else:
                max_force = 80.0

            # Apply force in desired direction
            fx = max_force * math.cos(desired_dir)
            fy = max_force * math.sin(desired_dir)
            sandbox.apply_seeker_force(fx, fy)
        else:
            # Not in slot, maintain position
            fx, fy = 0.0, 0.0
            sandbox.apply_seeker_force(fx, fy)

    # Cooldown management
    if state['cooldown_remaining'] > 0:
        state['cooldown_remaining'] -= 1
    else:
        # Check for cooldown trigger (not implemented due to mass uncertainty)
